import { sortTableRowsBy } from '@dreadnought/core';
const rows = [{ team: 'Design', age: 29 }, { team: 'Design', age: 25 }];
const sorted = sortTableRowsBy(rows, [{ compare: (a, b) => a.team.localeCompare(b.team), order: 'ascend' }, { compare: (a, b) => a.age - b.age, order: 'descend' }]);

import { getTableHeaderRows } from '@dreadnought/core';
type Column = { key: string; title: string; children?: readonly Column[] };
const columns: readonly Column[] = [{ key: 'name', title: 'Name' }, { key: 'contacts', title: 'Contacts', children: [{ key: 'email', title: 'Email' }, { key: 'phone', title: 'Phone' }] }];
const layout = getTableHeaderRows(columns);
const header = layout.rows.map(row => row.map(cell => ({ title: cell.column.title, colSpan: cell.colSpan, rowSpan: cell.rowSpan })));

import { sortTableRows } from '@dreadnought/core';
const people = [{ id: 1, name: 'Борис' }, { id: 2, name: 'Анна' }];
const sorted = sortTableRows(people, (a, b) => a.name.localeCompare(b.name), 'ascend');
